def gate(check, next_handler):
    @functools.wraps(next_handler)
    async def handler(request):
        identity = await check(request)          # this gate's own evidence
        if identity is None:                     # fail closed
            raise AccessDenied()
        token = current_identity.set(identity)   # inward: verified, not assumed
        try:
            return await next_handler(request)
        finally:
            current_identity.reset(token)
    return handler
